1	/**
2	 *
3	 * @copyright
4	 * Copyright 2022 Intel Corporation.
5	 * SPDX-License-Identifier: Apache-2.0
6	 *
7	 * @test ssl_sha
8	 *
9	 * The test calculates 3 different checksums (sha256, sha384 and sha512) for a
10	 * given random-generated buffer and compares the results against
11	 * pre-calculated golden values.
12	 *
13	 */
14	
15	#include "sandstone.h"
16	
17	#if SANDSTONE_SSL_BUILD
18	
19	#include "sandstone_ssl.h"
20	
21	#include <assert.h>
22	#include <string.h>
23	#include <stdlib.h>
24	#include <stdbool.h>
25	#include <sys/mman.h>
26	
27	#define PLAINTEXT_SIZE              (512UL)
28	#define SHA_GOLDEN_ELEMS            (1024UL)
29	#define SHA_MAX_OFFSET              (512UL)
30	
31	struct sha_elem
32	{
33	    uint8_t plain_text[PLAINTEXT_SIZE];
34	    uint8_t sha256sum[SHA256_DIGEST_LENGTH];
35	    uint8_t sha384sum[SHA384_DIGEST_LENGTH];
36	    uint8_t sha512sum[SHA512_DIGEST_LENGTH];
37	};
38	
39	struct sha_test
40	{
41	    uint8_t *arena;
42	    uint8_t arena_size;
43	    sha_elem golden_elements[SHA_GOLDEN_ELEMS];
44	};
45	
46	static void ssl_sha256(sha_elem *target)
47	{
48	    /* Create Context */
49	    EVP_MD_CTX *mdctx = s_EVP_MD_CTX_new();
50	
51	    /* Fetch algorithm */
52	    const EVP_MD *md = s_EVP_get_digestbyname("sha256");
53	
54	    /* Digest */
55	    unsigned int md_len = 0;
56	    s_EVP_DigestInit_ex(mdctx, md, NULL);
57	    s_EVP_DigestUpdate(mdctx, &target->plain_text[0], PLAINTEXT_SIZE);
58	    s_EVP_DigestFinal_ex(mdctx, &target->sha256sum[0], &md_len);
59	}
60	
61	static void ssl_sha384(sha_elem *target)
62	{
63	    /* Create Context */
64	    EVP_MD_CTX *mdctx = s_EVP_MD_CTX_new();
65	
66	    /* Fetch algorithm */
67	    const EVP_MD *md = s_EVP_get_digestbyname("sha384");
68	
69	    /* Digest */
70	    unsigned int md_len = 0;
71	    s_EVP_DigestInit_ex(mdctx, md, NULL);
72	    s_EVP_DigestUpdate(mdctx, &target->plain_text[0], PLAINTEXT_SIZE);
73	    s_EVP_DigestFinal_ex(mdctx, &target->sha384sum[0], &md_len);
74	}
75	
76	static void ssl_sha512(sha_elem *target)
77	{
78	    /* Create Context */
79	    EVP_MD_CTX *mdctx = s_EVP_MD_CTX_new();
80	
81	    /* Fetch algorithm */
82	    const EVP_MD *md = s_EVP_get_digestbyname("sha512");
83	
84	    /* Digest */
85	    unsigned int md_len = 0;
86	    s_EVP_DigestInit_ex(mdctx, md, NULL);
87	    s_EVP_DigestUpdate(mdctx, &target->plain_text[0], PLAINTEXT_SIZE);
88	    s_EVP_DigestFinal_ex(mdctx, &target->sha512sum[0], &md_len);
89	}
90	
91	static int ssl_sha_init(struct test* test)
92	{
93	    if (s_EVP_DigestInit_ex && s_EVP_DigestUpdate && s_EVP_DigestFinal_ex && s_EVP_get_digestbyname) {
94	        const size_t sha_offset = (random64() & 0x1ff) | 1;
95	        const size_t sha_arena_size = sha_offset + sizeof(sha_test);
96	        uint8_t *sha_arena = (uint8_t *) mmap(NULL, sha_arena_size, PROT_READ|PROT_WRITE, MAP_ANONYMOUS|MAP_PRIVATE, -1, 0);
97	
98	        sha_test *sha_test_ptr = (sha_test *)(&sha_arena[sha_offset]);
99	        test->data = sha_test_ptr;
100	
101	        sha_test_ptr->arena = sha_arena;
102	        sha_test_ptr->arena_size = sha_arena_size;
103	
104	        for (size_t i=0; i<SHA_GOLDEN_ELEMS; i++)
105	        {
106	            sha_elem *cursor = &sha_test_ptr->golden_elements[i];
107	            memset_random(&cursor->plain_text[0], PLAINTEXT_SIZE);
108	
109	            /* Calculate sha checksums */
110	            ssl_sha256(cursor);
111	            ssl_sha384(cursor);
112	            ssl_sha512(cursor);
113	        }
114	
115	        return EXIT_SUCCESS;
116	    }
117	    else {
118	        log_skip(TestResourceIssueSkipCategory, "OpenSSL library is not available or the current version is not supported");
119	        return EXIT_SKIP;
120	    }
121	}
122	
123	static int ssl_sha_run(struct test* test, int cpu)
124	{
125	    sha_test *sha_test_ptr = (sha_test *) test->data;
126	    sha_elem *golden_elements = &sha_test_ptr->golden_elements[0];
127	
128	    const size_t our_arena_size = SHA_MAX_OFFSET + sizeof(sha_elem);
129	    uint8_t *our_arena = (uint8_t *) mmap(NULL, our_arena_size, PROT_READ|PROT_WRITE, MAP_ANONYMOUS|MAP_PRIVATE, -1, 0);
130	
131	
132	    TEST_LOOP(test, 256) {
133	        const size_t our_offset = (random64() & 0x1ff) | 1;
134	        const size_t golden_idx = random64() & (SHA_GOLDEN_ELEMS - 1);
135	        sha_elem *golden_elem = &golden_elements[golden_idx];
136	
137	        sha_elem *our_elem = (sha_elem *) (&our_arena[our_offset]);
138	        memcpy(&our_elem->plain_text, &golden_elem->plain_text[0], PLAINTEXT_SIZE);
139	
140	        /* Calculate sha checksums */
141	        ssl_sha256(our_elem);
142	        ssl_sha384(our_elem);
143	        ssl_sha512(our_elem);
144	
145	        /* Check result against golden values */
146	        memcmp_or_fail(&our_elem->sha256sum[0], &golden_elem->sha256sum[0], SHA256_DIGEST_LENGTH,
147	                "sha256sum values does not match.");
148	        memcmp_or_fail(&our_elem->sha384sum[0], &golden_elem->sha384sum[0], SHA384_DIGEST_LENGTH,
149	                "sha384sum values does not match.");
150	        memcmp_or_fail(&our_elem->sha512sum[0], &golden_elem->sha512sum[0], SHA512_DIGEST_LENGTH,
151	                "sha512sum values does not match.");
152	    }
153	    return EXIT_SUCCESS;
154	}
155	
156	#else // !SANDSTONE_SSL_BUILD
157	
158	static int ssl_sha_init(struct test *test)
159	{
160	    log_skip(OsNotSupportedSkipCategory, "Not supported on this OS");
161	    return EXIT_SKIP;
162	}
163	
164	static int ssl_sha_run(struct test *test, int cpu)
165	{
166	    __builtin_unreachable();
167	}
168	
169	#endif
170	
171	DECLARE_TEST(openssl_sha, "Test calculating different sha checksums")
172	    .test_init = ssl_sha_init,
173	    .test_run = ssl_sha_run,
174	    .quality_level = TEST_QUALITY_PROD,
175	END_DECLARE_TEST
