9	#ifndef SANDSTONE_EIGEN_COMMON_H
10	#define SANDSTONE_EIGEN_COMMON_H
11	
12	/* Disable deprecation warnings in case the library used is >= 3.5.x. Once
13	 * majority of the distros move to 3.5 or higher,
14	 * https://github.com/opendcdiag/opendcdiag/pull/941 should be adopted. */
15	#define EIGEN_NO_DEPRECATED_WARNING
16	
17	#include <sandstone.h>
18	
19	#include <boost/type_traits/is_complex.hpp>
20	#include <Eigen/Eigenvalues>
21	
22	namespace {
23	template <typename SVD, int Dim> struct EigenSVDTest
24	{
25	    using Mat = typename SVD::MatrixType;
26	    struct eigen_test_data {
27	        Mat orig_matrix;
28	        Mat u_matrix;
29	        Mat v_matrix;
30	    };
31	
32	    [[gnu::noinline]] static void calculate_once(const Mat &orig_matrix, Mat &u, Mat &v)
33	    {
34	        SVD fullSvd(orig_matrix, Eigen::ComputeFullU | Eigen::ComputeFullV);
35	        u = fullSvd.matrixU();
36	        v = fullSvd.matrixV();
37	    }
38	
39	    template <typename FP> static inline std::enable_if_t<boost::is_complex<FP>::value>
40	    compare_or_fail(const FP *actual, const FP *expected, const char *name)
41	    {
42	        memcmp_or_fail(reinterpret_cast<const typename FP::value_type *>(actual),
43	                       reinterpret_cast<const typename FP::value_type *>(expected),
44	                       2 * Dim * Dim, name);
45	    }
46	
47	    template <typename FP> static inline std::enable_if_t<!boost::is_complex<FP>::value>
48	    compare_or_fail(const FP *actual, const FP *expected, const char *name)
49	    {
50	        memcmp_or_fail(actual, expected, Dim * Dim, name);
51	    }
52	
53	    static int init(struct test *test)
54	    {
55	        auto d = new eigen_test_data;
56	        d->orig_matrix = Mat::Random(Dim, Dim);
57	        calculate_once(d->orig_matrix, d->u_matrix, d->v_matrix);
58	        test->data = d;
59	        return EXIT_SUCCESS;
60	    }
61	
62	    static int cleanup(struct test *test)
63	    {
64	        delete static_cast<eigen_test_data *>(test->data);
65	        return EXIT_SUCCESS;
66	    }
67	
68	    static int run(struct test *test, int)
69	    {
70	        auto d = static_cast<eigen_test_data *>(test->data);
71	        do {
72	            Mat u, v;
73	            calculate_once(d->orig_matrix, u, v);
74	
75	            compare_or_fail(u.data(), d->u_matrix.data(), "Matrix U");
76	            compare_or_fail(v.data(), d->v_matrix.data(), "Matrix V");
77	        } while (test_time_condition(test));
78	        return EXIT_SUCCESS;
79	    }
80	};
81	
82	} // unnamed namespace
83	
84	#endif // SANDSTONE_EIGEN_COMMON_H
