2	/**
3	 * @copyright SPDX-License-Identifier: Apache-2.0
4	 *
5	 * @test fisttp_arm
6	 * @parblock
7	 * Floating-point to integer conversion (FCVTZS, round-toward-zero) via the Arm
8	 * Compute Library.  A fixed random table of float input (range [-100, 100]) is
9	 * generated at init and the golden int32 outputs are precomputed with
10	 * std::trunc.  Each run re-runs ACL's NECast (which issues FCVTZS) on the input
11	 * and compares the int32 output against the golden, plus a store/load
12	 * consistency check.  Pattern follows Intel OpenDCDiag's Eigen-based design.
13	 *
14	 * Per-thread ACL contexts (tensor + cast op) are preconfigured in init with
15	 * import_memory pointing at per-thread stack buffers, so ACL does not allocate
16	 * or own any memory that would need to survive sandstone's fork-per-iteration.
17	 *
18	 * Logging follows SDCShield convention: pass path is silent; on mismatch the
19	 * failing inputs and actual-vs-golden outputs are dumped via log_data() before
20	 * the thread is marked failed via report_fail_msg().
21	 * @endparblock
22	 */
23	
24	#include <sandstone.h>
25	#include <cstdint>
26	#include <cstdio>
27	#include <cstring>
28	#include <random>
29	#include <vector>
30	#include <memory>
31	#include <cmath>
32	#include <thread>
33	
34	// ACL 核心头文件
35	#include <arm_compute/runtime/NEON/NEFunctions.h>
36	#include <arm_compute/runtime/Scheduler.h>
37	#include <arm_compute/core/TensorInfo.h>
38	
39	static constexpr size_t NUM_ELEMENTS = 1024;
40	static constexpr float FLOAT_MIN = -100.0f;
41	static constexpr float FLOAT_MAX = 100.0f;
42	static constexpr uint64_t FIXED_SEED = 0x123456789ABCDEF0ULL;
43	
44	// 单个线程专属的资源上下文
45	struct PerThreadContext {
46	    alignas(128) float input[NUM_ELEMENTS];
47	    alignas(128) int32_t output[NUM_ELEMENTS];
48	    alignas(128) int32_t store_buf[NUM_ELEMENTS];
49	    alignas(128) int32_t reload_buf[NUM_ELEMENTS];
50	
51	    arm_compute::Tensor src_tensor{};
52	    arm_compute::Tensor dst_tensor{};
53	    arm_compute::NECast cast_op{};
54	};
55	
56	struct SharedTestData {
57	    std::vector<float> golden_input;
58	    std::vector<int32_t> golden_output;
59	    // 使用 unique_ptr 确保内存地址绝对固定，避免 resize/push_back 触发析构和深浅拷贝问题
60	    std::vector<std::unique_ptr<PerThreadContext>> thread_ctx;
61	};
62	
63	static inline int32_t truncate_to_int(float val) {
64	    return static_cast<int32_t>(std::trunc(val));
65	}
66	
67	// ============================================================================
68	// 初始化：生成固定随机输入，预计算黄金结果。所有线程共享同一份只读数据。
69	// 在单线程 init 阶段预先 configure 所有算子，确保多线程运行阶段零数据竞争。
70	// ============================================================================
71	static int fisttp_arm_init(struct test *test) {
72	    // 1. 禁用 ACL 内部多线程，防止 ACL 的内部工作线程与 Sandstone 的绑核线程发生竞争
73	    arm_compute::Scheduler::get().set_num_threads(1);
74	
75	    auto *shared_data = new (std::nothrow) SharedTestData;
76	    if (!shared_data) return EXIT_FAILURE;
77	
78	    shared_data->golden_input.resize(NUM_ELEMENTS);
79	    shared_data->golden_output.resize(NUM_ELEMENTS);
80	
81	    int max_cpus = num_cpus();
82	    if (max_cpus <= 0) max_cpus = static_cast<int>(std::thread::hardware_concurrency());
83	    if (max_cpus <= 0) max_cpus = 256;
84	
85	    shared_data->thread_ctx.reserve(max_cpus);
86	
87	    std::mt19937_64 rng(FIXED_SEED);
88	    std::uniform_real_distribution<float> dist(FLOAT_MIN, FLOAT_MAX);
89	
90	    for (size_t i = 0; i < NUM_ELEMENTS; ++i) {
91	        shared_data->golden_input[i] = dist(rng);
92	        shared_data->golden_output[i] = truncate_to_int(shared_data->golden_input[i]);
93	    }
94	
95	    // 2. 在单线程 Init 阶段预先初始化并 configure 所有算子，确保多线程运行阶段零数据竞争
96	    arm_compute::TensorInfo src_info(arm_compute::TensorShape(NUM_ELEMENTS), 1, arm_compute::DataType::F32);
97	    arm_compute::TensorInfo dst_info(arm_compute::TensorShape(NUM_ELEMENTS), 1, arm_compute::DataType::S32);
98	
99	    for (int i = 0; i < max_cpus; ++i) {
100	        auto ctx = std::make_unique<PerThreadContext>();
101	
102	        ctx->src_tensor.allocator()->init(src_info);
103	        ctx->dst_tensor.allocator()->init(dst_info);
104	
105	        ctx->src_tensor.allocator()->import_memory(ctx->input);
106	        ctx->dst_tensor.allocator()->import_memory(ctx->output);
107	
108	        // 核心安全保证：configure 仅在 init 阶段单线程调用一次
109	        ctx->cast_op.configure(&ctx->src_tensor, &ctx->dst_tensor, arm_compute::ConvertPolicy::WRAP);
110	
111	        shared_data->thread_ctx.push_back(std::move(ctx));
112	    }
113	
114	    test->data = shared_data;
115	    return EXIT_SUCCESS;
116	}
117	
118	// 运行测试：每次迭代调用 ACL NECast (FCVTZS) 并与 golden 比较
119	static int fisttp_arm_run(struct test *test, int cpu) {
120	    auto *shared_data = static_cast<SharedTestData*>(test->data);
121	    if (!shared_data) return EXIT_FAILURE;
122	
123	    size_t cpu_idx = (cpu >= 0 && static_cast<size_t>(cpu) < shared_data->thread_ctx.size())
124	                     ? static_cast<size_t>(cpu) : 0;
125	    auto &ctx = *shared_data->thread_ctx[cpu_idx];
126	
127	    do {
128	        // 1. 输入数据准备
129	        std::memcpy(ctx.input, shared_data->golden_input.data(), NUM_ELEMENTS * sizeof(float));
130	
131	        // 2. 压测运行：仅调用预先 configure 好的 run() 函数
132	        ctx.cast_op.run();
133	
134	        // 3. 结果校验（FCVTZS 转换为整数比对 + Cache 一致性比对）
135	        bool data_ok = (std::memcmp(ctx.output, shared_data->golden_output.data(), NUM_ELEMENTS * sizeof(int32_t)) == 0);
136	
137	        std::memcpy(ctx.store_buf, ctx.output, NUM_ELEMENTS * sizeof(int32_t));
138	        std::memcpy(ctx.reload_buf, ctx.store_buf, NUM_ELEMENTS * sizeof(int32_t));
139	        bool consistent = (std::memcmp(ctx.reload_buf, ctx.output, NUM_ELEMENTS * sizeof(int32_t)) == 0);
140	
141	        if (!data_ok || !consistent) {
142	            // Fail 详查：把本次输入与输出落进 yaml 的 data: 字段，再用 report_fail_msg
143	            // 记录失败位置（框架自动标 thread failed）。report_fail_msg 是 noreturn。
144	            // 定位首个不符元素
145	            int mismatch_idx = -1;
146	            for (size_t i = 0; i < NUM_ELEMENTS; ++i) {
147	                if (ctx.output[i] != shared_data->golden_output[i]) { mismatch_idx = (int)i; break; }
148	            }
149	            char ctx_msg[200];
150	            snprintf(ctx_msg, sizeof(ctx_msg),
151	                     "fisttp_arm (ACL): conversion mismatch on CPU %d at idx %d "
152	                     "(out=%d golden=%d, data_ok=%d, consistent=%d)",
153	                     cpu, mismatch_idx,
154	                     mismatch_idx >= 0 ? ctx.output[mismatch_idx] : 0,
155	                     mismatch_idx >= 0 ? shared_data->golden_output[mismatch_idx] : 0,
156	                     (int)data_ok, (int)consistent);
157	            log_data("fisttp input (float, 1024 elems)",
158	                     ctx.input, NUM_ELEMENTS * sizeof(float));
159	            log_data("fisttp output (int32 ACL FCVTZS result, 1024 elems)",
160	                     ctx.output, NUM_ELEMENTS * sizeof(int32_t));
161	            log_data("fisttp golden (std::trunc int32 result, 1024 elems)",
162	                     shared_data->golden_output.data(), NUM_ELEMENTS * sizeof(int32_t));
163	            report_fail_msg("%s", ctx_msg);
164	            // report_fail_msg 不返回
165	        }
166	
167	    } while (test_time_condition(test));
168	
169	    return EXIT_SUCCESS;
170	}
171	
172	static int fisttp_arm_finish(struct test *test) {
173	    auto *shared_data = static_cast<SharedTestData*>(test->data);
174	    if (shared_data) {
175	        delete shared_data;
176	    }
177	    test->data = nullptr;
178	    return EXIT_SUCCESS;
179	}
180	
181	// ============================================================================
182	// 测试声明
183	// ============================================================================
184	DECLARE_TEST(fisttp_arm, "Floating-point to integer conversion (FCVTZS) via Arm Compute Library")
185	    .groups = DECLARE_TEST_GROUPS(&group_math),
186	    .test_init = fisttp_arm_init,
187	    .test_run = fisttp_arm_run,
188	    .test_cleanup = fisttp_arm_finish,
189	    .quality_level = TEST_QUALITY_PROD
190	END_DECLARE_TEST
