    }

    /* golden = 1.0 * A * B + 0.0 * C (independent long-double reference) */
    data->golden = (float *)aligned_alloc_safe(64, ACL_DIM * ACL_DIM * sizeof(float));
    naive_gemm(A, B, data->golden);

